const courses=[{title:'Inglês na Palma da Mão',icon:'Hi!',tag:'ON-LINE',cat:'ingles',desc:'Inglês para situações reais, com a praticidade de aprender de onde você estiver.',detail:'Um curso on-line que aplica a metodologia PIXinBUILT ao aprendizado prático do inglês. Converse com a equipe para conhecer as turmas, os níveis e as condições.'},{title:'ID Inglês Express',icon:'↗',tag:'INTENSIVO',cat:'ingles',desc:'Um programa de 30 dias com 150 frases para usar em conversas do cotidiano.',detail:'Um intensivo voltado a situações como saudações, compras e restaurantes. A equipe ID pode orientar sobre a próxima turma e os requisitos para participar.'},{title:'Inglês & Espanhol EAD',icon:'Hola.',tag:'NO SEU RITMO',cat:'ingles espanhol',desc:'Flexibilidade para estudar inglês ou espanhol, com materiais exclusivos e suporte.',detail:'Cursos a distância de inglês e espanhol para encaixar o aprendizado na sua rotina. Consulte a escola sobre a organização das aulas e os níveis disponíveis.'},{title:'Curso de Pronúncia',icon:'/ə/',tag:'INGLÊS',cat:'ingles',desc:'Desenvolva uma fala mais clara e a compreensão do inglês que você escuta.',detail:'Uma experiência focada em pronúncia e compreensão do inglês falado. Converse com a ID para encontrar uma opção adequada ao seu momento.'},{title:'ID in Company',icon:'↗↗',tag:'EMPRESAS',cat:'empresas',desc:'Inglês conectado às reuniões, negociações e desafios reais da sua equipe.',detail:'Formação personalizada para as necessidades de comunicação do seu negócio. A equipe ID desenvolve uma proposta conforme os objetivos da empresa.'},{title:'Travel with ID',icon:'✈',tag:'VIAGEM',cat:'ingles',desc:'Mais autonomia para se comunicar e aproveitar cada experiência pelo mundo.',detail:'Um curso voltado a quem deseja usar o inglês em viagens, com situações práticas do dia a dia no exterior.'}];
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
function renderCourses(filter='all'){$('#course-grid').innerHTML=courses.map((c,i)=>filter==='all'||c.cat.includes(filter)?`<article class="course-card"><div class="course-top"><span class="course-icon">${c.icon}</span><span class="tag">${c.tag}</span></div><h3>${c.title}</h3><p>${c.desc}</p><button data-course="${i}">Conheça o curso <span>↗</span></button></article>`:'').join('')}
renderCourses();$$('[data-filter]').forEach(b=>b.onclick=()=>{$$('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderCourses(b.dataset.filter)});
document.addEventListener('click',e=>{const b=e.target.closest('[data-course]');if(!b)return;const c=courses[b.dataset.course];$('#detail-content').innerHTML=`<span class="tag">${c.tag}</span><h2>${c.title}</h2><p>${c.detail}</p><a class="btn red" href="https://wa.me/5571983627000?text=${encodeURIComponent('Olá! Quero saber mais sobre '+c.title+'.')}" target="_blank" rel="noopener">Fale com a ID <span>↗</span></a>`;$('#detail-dialog').showModal()});
const books=[['Inglês nas férias','Como manter a prática do inglês durante as férias?','Rotina leve.<br>Inglês presente.','ebook1-como-manter-a-pratica-do-ingles-durante-as-ferias/','✳'],['Acelere seu inglês','7 estratégias que vão acelerar seu inglês.','Pequenos passos.<br>Novas conversas.','e-books/','7↗'],['Inglês & carreira','Entrevista de emprego: por onde começar?','Seu próximo<br>grande passo.','e-books/','↗']];
function renderContent(type){$('#resources').innerHTML=type==='ebooks'?books.map(b=>`<article class="resource-card"><a class="book-art" href="https://id-idiomas.com.br/${b[3]}" target="_blank" rel="noopener" aria-label="Acessar ${b[1]}"><div><small>ID IDIOMAS · E-BOOK</small><span>${b[2]}</span><b>${b[4]}</b></div></a><small>E-BOOK GRATUITO · ${b[0].toUpperCase()}</small><h3>${b[1]}</h3><a class="text-link" href="https://id-idiomas.com.br/${b[3]}" target="_blank" rel="noopener">Acesse o material ↗</a></article>`).join(''):`<article class="blog-empty"><div><div class="eyebrow">BLOG ID IDIOMAS</div><h3 style="margin-top:15px">Continue explorando o idioma.</h3><p>Acompanhe os conteúdos e novidades publicados pela escola no blog oficial.</p></div><a class="btn dark" href="https://id-idiomas.com.br/blog/" target="_blank" rel="noopener">Visitar o blog <span>↗</span></a></article>`}renderContent('ebooks');$$('[data-content]').forEach(b=>b.onclick=()=>{$$('[data-content]').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderContent(b.dataset.content)});
$$('[data-login]').forEach(b=>b.onclick=()=>$('#login-dialog').showModal());$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
$$('[data-video]').forEach(b=>b.onclick=()=>{$('#video-frame').innerHTML=`<iframe src="https://www.youtube.com/embed/${b.dataset.video}?autoplay=1" title="Alunos ID Idiomas em conversação" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`;$('#video-dialog').showModal()});$('#video-dialog').addEventListener('close',()=>$('#video-frame').innerHTML='');
$('.menu').onclick=()=>{const open=$('nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',open)};$$('nav a').forEach(a=>a.onclick=()=>{$('nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false')});$('#year').textContent=new Date().getFullYear();
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
let portalName=localStorage.getItem('id-demo-name')||'Aluno ID';
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function portal(page='overview'){const name=escapeHtml(portalName);$('#portal').innerHTML=`<div class="portal-shell"><aside class="portal-sidebar"><a class="brand" href="#"><span class="brandmark">iD</span><span>MY ID</span></a>${[['overview','⌂','Visão geral'],['courses','▤','Meus cursos'],['materials','▧','Materiais'],['profile','◎','Meu perfil']].map(([id,icon,label])=>`<button data-page="${id}" class="${id===page?'active':''}">${icon} &nbsp; ${label}</button>`).join('')}<small>AMBIENTE DEMONSTRATIVO<br>Dados e progresso ilustrativos.</small><button id="portal-exit">← &nbsp; Voltar ao site</button></aside><div class="portal-main"><div class="portal-top"><span>MY ID / ${({overview:'Visão geral',courses:'Meus cursos',materials:'Materiais',profile:'Meu perfil'})[page]}</span><span class="demo-tag">Demonstração · Sem conexão com matrícula</span></div><div id="portal-view"></div></div></div>`;const view=$('#portal-view');if(page==='overview'||page==='courses')view.innerHTML=`<h1>${page==='overview'?`Olá, ${name}. <em>Let’s go!</em>`:'Seu próximo passo começa aqui.'}</h1><p>Continue sua jornada de novas conversas.</p>${page==='overview'?`<div class="portal-welcome"><div><div class="eyebrow">SUA JORNADA EM MOVIMENTO</div><h2>Um pouco a cada dia.<br>Um mundo de possibilidades.</h2><p>Escolha um curso para conhecer a organização da nova área do aluno.</p></div><span>↗</span></div>`:''}<div class="portal-cards"><article class="portal-card"><span class="tag">INGLÊS · DEMONSTRAÇÃO</span><h3>Advanced 2</h3><p>Turma presencial · Terças e quintas<br>15h20 · ID Vilas</p><div class="progress"><span></span></div><small>Exemplo de progresso · 65%</small><br><br><button class="btn red" data-page="materials">Explorar materiais <span>↗</span></button></article><article class="portal-card"><span class="tag">BIBLIOTECA · DEMONSTRAÇÃO</span><h3>Advanced 1</h3><p>Seus estudos também ficam com você.<br>Revisite os conteúdos do nível anterior.</p><div class="progress"><span style="width:100%;background:#798b59"></span></div><small>Exemplo de curso concluído</small><br><br><button class="btn dark" data-page="materials">Ver biblioteca <span>↗</span></button></article></div>`;
if(page==='materials')view.innerHTML=`<h1>Sua biblioteca. <em>Seu ritmo.</em></h1><p>Exemplo de organização dos materiais. Os conteúdos restritos dependem da integração com o portal atual.</p><div class="portal-card"><div class="eyebrow">ADVANCED 2 · MATERIAL DIDÁTICO</div><div class="material-row"><span>01 &nbsp; Apresentação do curso</span><button data-preview-material>Visualizar exemplo ↗</button></div><div class="material-row"><span>02 &nbsp; Prática de conversação</span><button data-preview-material>Visualizar exemplo ↗</button></div><div class="material-row"><span>03 &nbsp; Conteúdo da sua matrícula</span><a href="https://id-idiomas.com.br/" target="_blank" rel="noopener">Acessar site atual ↗</a></div></div><h2 style="font-size:25px;margin:30px 0 20px">Continue aprendendo</h2><a class="btn dark" href="https://id-idiomas.com.br/e-books/" target="_blank" rel="noopener">E-books gratuitos da ID <span>↗</span></a>`;
if(page==='profile')view.innerHTML=`<h1>Um espaço com a sua <em>identidade.</em></h1><p>Personalize o nome exibido nesta demonstração. Os dados ficam apenas neste navegador.</p><form id="profile-form" class="portal-form"><label>Nome de exibição<input name="displayName" value="${name}" maxlength="60" required autocomplete="nickname"></label><button class="btn red" type="submit">Salvar nome <span>✓</span></button></form>`;
$$('[data-page]').forEach(b=>b.onclick=()=>portal(b.dataset.page));$('#portal-exit').onclick=()=>{$('#portal').hidden=true;$('#public-site').hidden=false;$('header').hidden=false;$('.topline').hidden=false;$('footer').hidden=false;window.scrollTo(0,0)};$$('[data-preview-material]').forEach(b=>b.onclick=()=>{$('#detail-content').innerHTML='<span class="tag">CONTEÚDO ILUSTRATIVO</span><h2>Let’s start a conversation.</h2><p>Use estas perguntas como exemplo de uma atividade de conversação:</p><p>What is something new you would like to learn?<br>How could English help you reach that goal?<br>Tell a partner about a memorable trip.</p><p>Este exemplo foi criado para a demonstração e não faz parte do material oficial da ID.</p>';$('#detail-dialog').showModal()});if($('#profile-form'))$('#profile-form').onsubmit=e=>{e.preventDefault();portalName=new FormData(e.target).get('displayName').trim()||'Aluno ID';localStorage.setItem('id-demo-name',portalName);portal('profile');toast('Nome salvo neste navegador.')};}
$('#demo-enter').onclick=()=>{$('#login-dialog').close();$('#public-site').hidden=true;$('header').hidden=true;$('.topline').hidden=true;$('footer').hidden=true;$('#portal').hidden=false;portal();window.scrollTo(0,0)};
